// ===ALKEMIJANA:TAROT_CARD_TEXTS:START===
// Nazivi i značenja (uspravno/obrnuto) po špilu za Virtualni tarot — uređuje se
// u admin tabu "Tarot karte". "upright" se prikazuje i uz "Kartu dana" na
// početnoj te uz uvećanu kartu na tarot stolu (v. tarot/tarot.js, tarot/tarot-render.js).
let TAROT_CARD_TEXTS = {
  "rws": {
    "fool": { "name": "Luda", "upright": "Luda je karta novog početka i skoka u nepoznato — spontanosti, znatiželje i vjere da će se put otvoriti dok hodaš. Nosi svježinu i hrabrost da kreneš bez tereta prošlih iskustava i bez straha od tuđeg suda. U starijim tumačenjima podsjeća i na nepromišljenost, pa je poruka jednostavna: kreni slobodno, ali ostani barem malo prisebna.", "reversed": "Obrnuto upozorava na nepromišljenost, rizik bez razmišljanja i odluke koje mogu skupo koštati. Vrijeme je usporiti i provjeriti plan prije sljedećeg koraka." },
    "magician": { "name": "Mag", "upright": "Mag je karta volje pretvorene u djelo — vještine, snalažljivosti i sposobnosti da zamisao postane stvarnost. Svi alati koje trebaš već su pred tobom; pitanje je samo hoćeš li ih usmjeriti s namjerom. Poziva na fokus, samopouzdanje i preuzimanje inicijative.", "reversed": "Obrnuto ukazuje na manipulaciju, prijevaru ili neiskorišten potencijal — vještina se koristi na pogrešan način ili se uopće ne koristi. Provjeri jesu li namjere, tvoje ili tuđe, iskrene." },
    "high-priestess": { "name": "Velika svećenica", "upright": "Velika svećenica čuva prag između svjesnog i skrivenog — nosi intuiciju, tihu mudrost i tajne koje se još nisu otkrile. Poziva na strpljenje i osluškivanje unutarnjeg glasa prije nego što se nešto izgovori naglas. Odgovori koje tražiš već su u tebi; treba im samo tišina da isplivaju.", "reversed": "Obrnuto govori o potisnutoj intuiciji, tajnama koje izlaze na vidjelo ili gubitku unutarnjeg mira. Vrijeme je vratiti se tišini i ponovno osluhnuti sebe." },
    "empress": { "name": "Carica", "upright": "Carica donosi obilje, plodnost i toplinu prirode koja se ne žuri. Govori o njegovanju — sebe, ideje, odnosa ili doma — i o zadovoljstvu u stvaralačkom, osjetilnom životu. Rast dolazi kad dopustiš stvarima da sazriju svojim ritmom.", "reversed": "Obrnuto može značiti blokadu kreativnosti, zanemarivanje sebe ili pretjeranu ovisnost o drugima. Podsjeća da se njegovanje mora vratiti i tebi samoj." },
    "emperor": { "name": "Car", "upright": "Car predstavlja red, stabilnost i čvrstu vlast nad vlastitim životom. Nosi zaštitu, razum i snagu volje — temelje na kojima se gradi sigurnost. Poziva na jasne granice i odgovornost, uz vodstvo koje dolazi iz mirne čvrstine, a ne iz krutosti.", "reversed": "Obrnuto upozorava na krutost, prekomjernu kontrolu ili, suprotno, gubitak strukture i discipline. Vrijedi pronaći ravnotežu između reda i fleksibilnosti." },
    "hierophant": { "name": "Svećenik", "upright": "Svećenik nosi tradiciju, zajedničke vrijednosti i učenje kroz provjerene puteve. Povezuje se s obvezom, savezništvom i pripadanjem nečemu većem — mentorstvu, zajednici ili duhovnoj praksi. Podsjeća da je ponekad mudro osloniti se na ono što je već isprobano, uz pažnju da te okvir ne sputa previše.", "reversed": "Obrnuto može značiti pobunu protiv konvencija, netradicionalan put ili osjećaj gušenja unutar krutih pravila. Ponekad je vrijeme da odbaciš tuđa uvjerenja i nađeš vlastiti put." },
    "lovers": { "name": "Ljubavnici", "upright": "Ljubavnici govore o privlačnosti, ljubavi i skladu koji nastaje kad se vrijednosti dvoje ljudi poklope. Nose i temu izbora donesenog srcem — raskrižja na kojem biraš ono što je za tebe istinito. Kušnje koje su iza tebe sada se razrješavaju u povezanost.", "reversed": "Obrnuto ukazuje na neusklađenost vrijednosti, tešku odluku ili nesigurnost u vezi. Vrijedi preispitati temelji li se izbor na strahu ili na istini." },
    "chariot": { "name": "Kočija", "upright": "Kočija je pobjeda voljom — sposobnost da suprotstavljene sile usmjeriš u isti smjer i kreneš naprijed. Traži samopouzdanje, fokus i odlučnost usred izazova. Uspjeh dolazi onome tko drži uzde čvrsto, uz oprez da ta snaga ne preraste u tvrdoglavost.", "reversed": "Obrnuto znači gubitak smjera, nedostatak discipline ili osjećaj da kontrola izmiče. Vrijeme je zastati i ponovno usmjeriti energiju prije nego nastaviš." },
    "strength": { "name": "Snaga", "upright": "Snaga (u starijim špilovima \"Postojanost\") nosi hrabrost, energiju i plemenitost duha. Ne radi se o sirovoj sili, nego o strpljenju i suosjećanju koji pripitomljuju i najveće prepreke. Prava moć ovdje je nježna — i upravo zato potpuna.", "reversed": "Obrnuto ukazuje na nesigurnost, samosumnju ili trenutke kad nedostaje strpljenja. Podsjeća da je u redu tražiti podršku dok ponovno pronalaziš unutarnju snagu." },
    "hermit": { "name": "Pustinjak", "upright": "Pustinjak se povlači od buke svijeta u potrazi za unutarnjim svjetlom. Nosi razboritost, promišljenost i mudrost stečenu vlastitim iskustvom. Poziva na trenutak samoće koji liječi i razbistri — odgovor se često ne nalazi vani, nego u tišini.", "reversed": "Obrnuto može značiti izolaciju koja je otišla predaleko ili izbjegavanje potrebne introspekcije. Vrijeme je izaći iz sebe, ali bez žurbe." },
    "wheel-of-fortune": { "name": "Kotač sreće", "upright": "Kotač sreće donosi sudbinu, sreću i uzlazni okret događaja. Podsjeća da je promjena jedina stalnost — ono što je dugo čekalo sada dolazi. Vrijedi prepoznati priliku i uhvatiti val dok se kotač penje.", "reversed": "Obrnuto govori o osjećaju smole, otporu promjeni ili ciklusu koji se ponavlja dok se ne nauči lekcija. Podsjeća da i teška razdoblja prolaze." },
    "justice": { "name": "Pravda", "upright": "Pravda traži poštenje, jasnoću i preuzimanje odgovornosti za vlastite postupke. Govori o ravnoteži uzroka i posljedice — što posiješ, to i žanješ. Ono što je ispravno na kraju dobiva svoje priznanje, čak i kad dolazi sporo.", "reversed": "Obrnuto ukazuje na nepravdu, izbjegavanje odgovornosti ili odluku koja čeka predugo. Vrijeme je suočiti se s posljedicama i ispraviti nepravilnost." },
    "hanged-man": { "name": "Obješeni čovjek", "upright": "Obješeni čovjek nudi pogled iz sasvim drugog kuta — mudrost koja dolazi kad prestaneš gurati. Nosi predaju, strpljenje i sposobnost razlučivanja izoštrenu kroz mirovanje. Ponekad je najveći uvid u tome da svjesno zastaneš i pustiš.", "reversed": "Obrnuto može značiti otpor promjeni perspektive ili osjećaj da si žrtvovao previše bez razloga. Podsjeća da predaja ima smisla samo kad je svjesna, ne prisilna." },
    "death": { "name": "Smrt", "upright": "Smrt najavljuje kraj jednog poglavlja da bi moglo početi sljedeće — rijetko doslovan kraj, gotovo uvijek transformaciju. Ono što je odslužilo svoju svrhu sada odlazi, ma koliko se za njega držali. Iz tog rastanka oslobađa se prostor za nešto novo i istinitije.", "reversed": "Obrnuto govori o otporu promjeni, strahu od kraja ili zastoju usred tranzicije. Ono što je trebalo završiti, otezanje samo produžuje bol." },
    "temperance": { "name": "Umjerenost", "upright": "Umjerenost miješa suprotnosti u skladnu cjelinu — strpljenje, mjeru i postupan napredak. Poziva na ravnotežu umjesto krajnosti i na povjerenje u proces koji se ne žuri. Iscjeljenje i mir dolaze iz prave mjere.", "reversed": "Obrnuto ukazuje na neravnotežu, krajnosti ili nestrpljenje s procesom. Vrijeme je usporiti i vratiti se umjerenosti." },
    "devil": { "name": "Vrag", "upright": "Vrag pokazuje lance koje često sami sebi stavljamo — navike, strahove ili ovisnosti koje nas drže zarobljenima. Nosi i snažnu, sirovu privlačnost koja zna zavesti. Poruka je ipak oslobađajuća: čim prepoznaš iluziju kontrole koju nešto ima nad tobom, lanac popušta.", "reversed": "Obrnuto najavljuje oslobađanje od lanaca — svijest o ovisnosti ili obrascu koji si konačno spremna prekinuti. Snaga se vraća onog trenutka kad prepoznaš iluziju." },
    "tower": { "name": "Kula", "upright": "Kula je nagla promjena koja ruši ono što je bilo izgrađeno na krivim temeljima. Iako potresna, ta oluja čisti prostor od iluzija i otkriva istinu koja se dotad skrivala. Nakon rušenja često dolazi neočekivano olakšanje i mogućnost da se gradi stabilnije.", "reversed": "Obrnuto može značiti odgođenu krizu koja se ionako približava, ili strah od promjene koja je već neizbježna. Ponekad je bolje pustiti da se sruši ono što više ne drži." },
    "star": { "name": "Zvijezda", "upright": "Zvijezda donosi nadu, iscjeljenje i tihu vjeru nakon teškog razdoblja. Nosi obnovu i nadahnuće — osjećaj da su, nakon oblaka, bolji dani ponovno na putu. Dovoljno je pratiti svjetlo koje već osjećaš i dopustiti si da vjeruješ.", "reversed": "Obrnuto govori o izgubljenoj nadi, razočaranju ili osjećaju da je vjera uzalud. Podsjeća da svjetlo ostaje čak i kad ga trenutno ne vidiš." },
    "moon": { "name": "Mjesec", "upright": "Mjesec vodi kroz maglu neizvjesnosti, snova i onoga što nije posve jasno. Podsjeća da strahovi i iluzije u polumraku znaju izgledati veći nego što jesu. Poziva te da se osloniš na intuiciju i ne žuriš kroz nepoznato dok se put ne razbistri.", "reversed": "Obrnuto ukazuje na razjašnjenje — magla se počinje dizati, a istina izlazi na vidjelo. Strahovi koji su mučili počinju gubiti snagu." },
    "sun": { "name": "Sunce", "upright": "Sunce je radost, vitalnost i jasnoća bez skrivenih namjera — jedna od najvedrijih karata špila. Najavljuje uspjeh, toplinu i osjećaj da je, makar nakratko, sve na svom mjestu. Dopusti si da se raduješ bez zadrške.", "reversed": "Obrnuto može značiti privremeno zamagljenu radost, odgođen uspjeh ili potrebu da potražiš svjetlo u sebi. Sreća je i dalje na dohvat, samo malo dalje." },
    "judgement": { "name": "Sud", "upright": "Sud je poziv na buđenje — pogled unatrag koji donosi razumijevanje i poticaj da kreneš prema autentičnijoj verziji sebe. Govori o obnovi, oprostu i prekretnici na kojoj se nešto zaokružuje. Vrijeme je odgovoriti na unutarnji poziv i prihvatiti novo poglavlje.", "reversed": "Obrnuto govori o samokritici, propuštenom pozivu ili otporu prema promjeni koja se traži. Vrijeme je oprostiti sebi i ponovno poslušati unutarnji glas." },
    "world": { "name": "Svijet", "upright": "Svijet obilježava zaokruženje jednog ciklusa — cilj je postignut, krug se zatvorio. Nosi ispunjenje, cjelovitost i osjećaj da su svi dijelovi konačno posloženi. Često najavljuje i putovanje ili novi horizont — ostvarenje koje dolazi zajedno s pokretom naprijed.", "reversed": "Obrnuto ukazuje na nedovršen posao, kašnjenje ili osjećaj da cilj izmiče na zadnjoj prepreci. Ono što nedostaje često je samo posljednji, mali korak." },

    "wands-ace": { "name": "As štapova", "upright": "As štapova iskra je nove strasti, ideje ili poduzetnog pothvata spremnog da krene. Nosi stvaralačku energiju i početak koji budi entuzijazam. Sada je trenutak da uhvatiš tu iskru dok je svježa.", "reversed": "Obrnuto znači odgođen početak, nedostatak motivacije ili ideju koja još nije sazrela za pokretanje." },
    "wands-02": { "name": "Dvojka štapova", "upright": "Dvojka štapova stoji na pragu odluke — plan je postavljen, obzor otvoren, ostaje odabrati smjer. Nosi i naslućivanje uspjeha i obilja koje takva hrabrost može donijeti. Vizija bez prvog koraka ostaje tek zamisao.", "reversed": "Obrnuto ukazuje na strah od nepoznatog ili neodlučnost koja koči sljedeći korak." },
    "wands-03": { "name": "Trojka štapova", "upright": "Trojka štapova gleda prema obzoru dok prvi rezultati truda počinju stizati. Vrijeme je za strpljivo širenje, suradnju i pogled unaprijed. Ono što si pokrenula počinje se vraćati.", "reversed": "Obrnuto može značiti kašnjenja, prepreke u planovima ili nerealna očekivanja." },
    "wands-04": { "name": "Četvorka štapova", "upright": "Četvorka štapova slavi proslavu, dom i zajedništvo nakon uloženog truda. Nosi sklad, stabilnost i radost dijeljenu s bliskima. Trenutak je da zastaneš i uživaš u onome što je izgrađeno.", "reversed": "Obrnuto govori o nestabilnosti kod kuće ili odgođenoj proslavi." },
    "wands-05": { "name": "Petica štapova", "upright": "Petica štapova donosi trvenje, natjecanje i sukobljene interese koji traže glasan dogovor. Energija je živa, ponekad naporna, ali iz nje može izrasti bolje rješenje. Vrijedi se uključiti, no birati bitke.", "reversed": "Obrnuto znači izbjegavanje sukoba koji se ionako mora riješiti, ili nepotrebno zaoštravanje." },
    "wands-06": { "name": "Šestica štapova", "upright": "Šestica štapova javlja pobjedu, priznanje i zaslužene čestitke. Nosi trijumf i ispunjenje očekivanja. Vrijeme je primiti pohvalu i povjerenje koje ti drugi ukazuju.", "reversed": "Obrnuto ukazuje na odgođeno priznanje, samosumnju ili strah od neuspjeha." },
    "wands-07": { "name": "Sedmica štapova", "upright": "Sedmica štapova traži da braniš svoj stav i prostor usred izazova ili konkurencije. Nosi hrabrost i upornost onoga tko drži poziciju. Ostaneš li vjerna sebi, prednost je na tvojoj strani.", "reversed": "Obrnuto može značiti preplavljenost izazovima ili odustajanje od obrane vlastite pozicije." },
    "wands-08": { "name": "Osmica štapova", "upright": "Osmica štapova je nagli, ubrzani napredak — nakon čekanja stvari se pokreću brzo. Nose je vijesti, poruke i događaji koji stižu bez odgode. Prati zamah dok traje.", "reversed": "Obrnuto znači kašnjenja, frustraciju ili loše protumačene poruke." },
    "wands-09": { "name": "Devetka štapova", "upright": "Devetka štapova pokazuje umor od prijeđenog puta, ali i otpornost sabranu iz iskustva. Nosi snagu u naizgled nepovoljnoj situaciji i posljednju rezervu izdržljivosti. Ostani budna — cilj je bliže nego što se čini.", "reversed": "Obrnuto ukazuje na iscrpljenost ili obrambeni stav koji šteti više nego pomaže." },
    "wands-10": { "name": "Desetka štapova", "upright": "Desetka štapova nosi težinu preuzetih obveza — uspjeh je stigao, ali s njim i teret. Vrijedi razmotriti što je uistinu potrebno nositi dalje, a što možeš spustiti. Ne moraš sve raditi sama.", "reversed": "Obrnuto govori o pregorijevanju ili potrebi da konačno podijeliš teret s drugima." },
    "wands-page": { "name": "Paž štapova", "upright": "Paž štapova nosi svježu, znatiželjnu energiju istraživača spremnog na nove pothvate. Najavljuje ideju, vijest ili poruku koja budi entuzijazam. Prati taj poticaj i vidi kamo vodi.", "reversed": "Obrnuto može značiti nepromišljene odluke ili vijest koja kasni." },
    "wands-knight": { "name": "Vitez štapova", "upright": "Vitez štapova juri naprijed hrabro i strastveno, gladan akcije i pustolovine. Nosi promjenu, pokret i energiju koja teško miruje. Podsjeća da i najžešća strast treba malo smjera da ne izgori prebrzo.", "reversed": "Obrnuto ukazuje na impulzivnost, žurbu bez plana ili nestrpljenje." },
    "wands-queen": { "name": "Kraljica štapova", "upright": "Kraljica štapova zrači samopouzdanjem, toplinom i neovisnošću koja privlači druge. Vodi srcem i djelom istovremeno, sigurna u vlastitu vrijednost. Njezina karizma otvara i vrata i prilike.", "reversed": "Obrnuto znači nesigurnost, ljubomoru ili gubitak samopouzdanja." },
    "wands-king": { "name": "Kralj štapova", "upright": "Kralj štapova vodi vizijom, hrabrošću i prirodnim autoritetom poduzetnika. Nosi poštenje, odlučnost i sposobnost da ideju pretvori u pokret. Inspirira druge vlastitim primjerom.", "reversed": "Obrnuto govori o autoritarnosti, nestrpljenju ili nerealnim očekivanjima od drugih." },

    "cups-ace": { "name": "As pehara", "upright": "As pehara prelijeva se novom emocijom — ljubavlju, radošću ili duhovnim otvaranjem srca. Nosi obilje osjećaja i početak nečeg nježnog. Dopusti osjećajima da slobodno poteku.", "reversed": "Obrnuto znači potisnute emocije, prazninu ili emocionalni blok." },
    "cups-02": { "name": "Dvojka pehara", "upright": "Dvojka pehara slavi povezanost, uzajamnost i sklad između dvoje. Nosi ljubav, prijateljstvo i susret ravnopravnih. Ono što se gradi počiva na iskrenosti i međusobnom poštovanju.", "reversed": "Obrnuto ukazuje na neravnotežu u odnosu ili nesuglasje koje treba razgovor." },
    "cups-03": { "name": "Trojka pehara", "upright": "Trojka pehara slavi prijateljstvo, zajedništvo i radost dijeljenu s onima koji te podržavaju. Nosi proslavu, zahvalnost i sretan ishod. Vrijeme je uživati u zajednici oko sebe.", "reversed": "Obrnuto može značiti pretjerivanje, tračeve ili osjećaj isključenosti iz zajednice." },
    "cups-04": { "name": "Četvorka pehara", "upright": "Četvorka pehara pokazuje trenutak zasićenosti ili nezadovoljstva usred obilja koje se ne primjećuje. Podsjeća da vrijedi podignuti pogled — nova prilika već čeka. Ponekad je sreća bliže nego što se čini.", "reversed": "Obrnuto govori o buđenju iz apatije i ponovnom otvaranju prema prilikama." },
    "cups-05": { "name": "Petica pehara", "upright": "Petica pehara oplakuje gubitak, ali podsjeća da nešto vrijedno ipak ostaje. Iza tuge stoje pehari koji su još uspravni, čim se okreneš od onoga što je prosuto. Nosi i utjehu onoga što se prenosi i ostaje.", "reversed": "Obrnuto znači prihvaćanje gubitka i okretanje prema onome što je preostalo." },
    "cups-06": { "name": "Šestica pehara", "upright": "Šestica pehara vraća toplinu djetinjstva, nostalgiju i iskrenu dobrotu bez skrivenih namjera. Nosi ugodne uspomene i susrete koji liječe. Prošlost ovdje donosi utjehu, a ne teret.", "reversed": "Obrnuto ukazuje na zarobljenost u prošlosti ili nezdravu nostalgiju." },
    "cups-07": { "name": "Sedmica pehara", "upright": "Sedmica pehara nudi mnoštvo mogućnosti obavijenih maglom mašte i sanjarenja. Podsjeća da je potrebna jasnoća prije nego odabereš pravi put među privlačnim slikama. Ne mora sve što blista biti ono pravo.", "reversed": "Obrnuto govori o jasnoći nakon razdoblja zbunjenosti — vrijeme je za konkretan izbor." },
    "cups-08": { "name": "Osmica pehara", "upright": "Osmica pehara okreće leđa onome što više ne ispunjava, u potrazi za dubljim smislom. Nosi hrabar odlazak od udobnog radi autentičnog. Ono što ostavljaš možda je manje važno nego što se činilo.", "reversed": "Obrnuto može značiti strah od promjene koja je ipak nužna, ili povratak onome što je već napušteno." },
    "cups-09": { "name": "Devetka pehara", "upright": "Devetka pehara nosi zadovoljstvo, ispunjenje i osjećaj da su želje uslišane. Zovu je i \"kartom želje\" — trenutkom kad se dobro osjećaš u vlastitoj koži. Vrijeme je uživati u onome što si sebi izgradila.", "reversed": "Obrnuto ukazuje na površno zadovoljstvo ili nezasitnost koja ne donosi mir." },
    "cups-10": { "name": "Desetka pehara", "upright": "Desetka pehara slika sklad, obiteljsku sreću i emocionalno ispunjenje koje nadilazi pojedinca. Nosi mir srca i puninu ljubavi i prijateljstva. Ovo je karta trajnog zadovoljstva dijeljenog s voljenima.", "reversed": "Obrnuto znači obiteljske napetosti ili osjećaj da sklad postoji samo na površini." },
    "cups-page": { "name": "Paž pehara", "upright": "Paž pehara donosi nježnu, maštovitu poruku ili nova emocionalna otkrića. Nosi otvorenost srca, kreativnost i tihu intuiciju. Poziva te da poslušaš osjećaj koji se javlja.", "reversed": "Obrnuto može značiti emocionalnu nezrelost ili poruku koju je teško protumačiti." },
    "cups-knight": { "name": "Vitez pehara", "upright": "Vitez pehara jaše vođen romantikom, idealima i pozivom srca. Nosi ponudu, poziv ili gestu koja dolazi iz iskrenih osjećaja. Približava se nešto lijepo — dopusti mu da priđe.", "reversed": "Obrnuto ukazuje na nerealna očekivanja u ljubavi ili obećanja koja se ne ispunjavaju." },
    "cups-queen": { "name": "Kraljica pehara", "upright": "Kraljica pehara njeguje duboku empatiju i emocionalnu mudrost. Vodi osjećajima, ali s mirnoćom koja druge umiruje i razumije. Njezina toplina daje sigurnost svima oko nje.", "reversed": "Obrnuto znači preplavljenost tuđim emocijama ili zanemarivanje vlastitih potreba." },
    "cups-king": { "name": "Kralj pehara", "upright": "Kralj pehara vlada emocijama sa zrelošću i stabilnošću — suosjećajan, ali pribran. Spaja srce i razum, ostajući miran i usred oluje. Primjer je kako biti topao, a istovremeno čvrst.", "reversed": "Obrnuto govori o emocionalnoj nestabilnosti skrivenoj iza mirnog lica." },

    "swords-ace": { "name": "As mačeva", "upright": "As mačeva sječe kroz konfuziju do jasne istine ili nove ideje. Nosi mentalnu bistrinu, odlučnost i snagu — u ljubavi jednako kao u sukobu. Trenutak je da stvari nazoveš pravim imenom.", "reversed": "Obrnuto znači zbrku, loše prosuđenu odluku ili istinu izrečenu na pogrešan način." },
    "swords-02": { "name": "Dvojka mačeva", "upright": "Dvojka mačeva pokazuje zastoj i odgađanje odluke dok se izbjegava suočavanje. Nosi i privremenu ravnotežu i primirje, ali ono ne može trajati vječno. Vrijeme je skinuti povez s očiju i odabrati.", "reversed": "Obrnuto ukazuje na produljeno izbjegavanje odluke ili informacije koje su konačno izašle na vidjelo." },
    "swords-03": { "name": "Trojka mačeva", "upright": "Trojka mačeva nosi bol istine, razočaranja ili rastanka — jednu od iskrenijih, ali i teže karata. Ipak, ta jasnoća, koliko god oštra, otvara put ozdravljenju. Ono što boli sada oslobađa prostor za zdraviji odnos prema sebi.", "reversed": "Obrnuto govori o oporavku od boli ili, suprotno, o rani koja se ne zacjeljuje." },
    "swords-04": { "name": "Četvorka mačeva", "upright": "Četvorka mačeva traži predah — oporavak, tišinu i mentalni odmor prije sljedeće bitke. Nosi povlačenje koje nije bijeg, nego priprema. Zaustavljanje sada vraća ti snagu.", "reversed": "Obrnuto može značiti nasilan povratak u akciju prije nego što je oporavak dovršen." },
    "swords-05": { "name": "Petica mačeva", "upright": "Petica mačeva upozorava na pobjedu koja gorko okusi — sukob u kojem svi ponešto izgube. Vrijedi promisliti je li borba uopće vrijedna nastavka. Ponekad je najmudrije spustiti mač.", "reversed": "Obrnuto ukazuje na pomirenje nakon sukoba ili priznanje vlastite uloge u njemu." },
    "swords-06": { "name": "Šestica mačeva", "upright": "Šestica mačeva vodi prema mirnijim vodama, ostavljajući teškoće iza sebe. Nosi putovanje, prijelaz i postupno smirivanje. Ideš prema boljem, čak i ako je put još pomalo neizvjestan.", "reversed": "Obrnuto govori o otporu promjeni ili nedovršenom prijelazu." },
    "swords-07": { "name": "Sedmica mačeva", "upright": "Sedmica mačeva govori o strategiji, snalažljivosti i potrebi da djeluješ promišljeno. Nosi i upozorenje na prečace ili neiskrenost — svoju ili tuđu. Vrijedi provjeriti igra li se pošteno.", "reversed": "Obrnuto može značiti razotkrivanje neiskrenosti ili priznanje vlastitih prečaca." },
    "swords-08": { "name": "Osmica mačeva", "upright": "Osmica mačeva prikazuje osjećaj zarobljenosti koji je često samonametnut. Nosi ograničenja koja izgledaju veća nego što uistinu jesu. Izlaz postoji čim prestaneš vjerovati da ga nema.", "reversed": "Obrnuto znači oslobađanje iz osjećaja zarobljenosti — konačno vidiš izlaz." },
    "swords-09": { "name": "Devetka mačeva", "upright": "Devetka mačeva nosi tjeskobu, brige i misli koje se vrte u krug usred noći. Podsjeća da strahovi u glavi znaju biti mnogo veći nego u stvarnosti. Ono što te muči često izgleda drukčije na dnevnom svjetlu.", "reversed": "Obrnuto ukazuje na olakšanje nakon razdoblja tjeskobe, ili brige koje su bile pretjerane." },
    "swords-10": { "name": "Desetka mačeva", "upright": "Desetka mačeva označava bolan, ali definitivan kraj — dno s kojeg vodi samo put prema gore. Ono najgore je iza tebe; ono što slijedi je oporavak. Iza najtamnijeg trenutka već sviće.", "reversed": "Obrnuto govori o otporu prihvaćanju kraja koji je zapravo neizbježan." },
    "swords-page": { "name": "Paž mačeva", "upright": "Paž mačeva budan je, znatiželjan promatrač spreman učiti i postavljati pitanja. Nosi oštar um, opreznost i potrebu za jasnim razmišljanjem. Najavljuje vijest ili istinu koju vrijedi dobro pogledati.", "reversed": "Obrnuto može značiti tračeve, nepromišljene riječi ili informacije primljene prebrzo." },
    "swords-knight": { "name": "Vitez mačeva", "upright": "Vitez mačeva juri odlučno prema cilju, brzo i izravno, ponekad prebrzo. Nosi hitro djelovanje, hrabrost i jasnu komunikaciju. Podsjeća da snaga uma treba i malo strpljenja.", "reversed": "Obrnuto ukazuje na nepromišljenost, žurbu ili sukob izazvan nestrpljenjem." },
    "swords-queen": { "name": "Kraljica mačeva", "upright": "Kraljica mačeva vidi jasno kroz iluzije i vodi razumom, iskrenošću i nezavisnošću. Njezina snaga je u britkoj istini izrečenoj bez suvišnih riječi. Iza njezine ozbiljnosti krije se iskustvo, ne hladnoća.", "reversed": "Obrnuto znači oštrinu koja povređuje ili hladnoću kao obranu od boli." },
    "swords-king": { "name": "Kralj mačeva", "upright": "Kralj mačeva vlada logikom, autoritetom i nepristranom prosudbom. Odluke donosi bistre glave, na temelju činjenica, a ne emocija. Njegova je moć u jasnoći i pravednosti.", "reversed": "Obrnuto govori o hladnoj manipulaciji ili zlouporabi autoriteta." },

    "pentacles-ace": { "name": "As pentakla", "upright": "As pentakla donosi novu priliku u poslu, financijama ili opipljivom svijetu. Nosi sjeme uspjeha, blagostanja i konkretnog rasta. Uz njegu, iz njega može izrasti nešto stabilno i trajno.", "reversed": "Obrnuto znači propuštenu priliku ili nesigurnost oko financija." },
    "pentacles-02": { "name": "Dvojka pentakla", "upright": "Dvojka pentakla žonglira s više obveza, tražeći ravnotežu usred promjenjivih okolnosti. Nosi prilagodljivost, ali i vijesti ili poruke koje traže pažnju. Dok se sve posloži, ključno je ostati gibak.", "reversed": "Obrnuto ukazuje na neravnotežu, prezauzetost ili nesigurno žongliranje obavezama." },
    "pentacles-03": { "name": "Trojka pentakla", "upright": "Trojka pentakla slavi vještinu, suradnju i kvalitetan rad prepoznat od drugih. Nosi majstorstvo, ugled i zajednički trud koji gradi nešto trajno. Ono što stvarate zajedno vrijedi više od zbroja.", "reversed": "Obrnuto može značiti lošu suradnju ili rad koji nije prepoznat." },
    "pentacles-04": { "name": "Četvorka pentakla", "upright": "Četvorka pentakla čvrsto drži stečeno, tražeći sigurnost kroz kontrolu i štednju. Nosi stabilnost, ali i podsjetnik da pretjerano stiskanje zna zakočiti rast. Sigurnost je dobra dok ne postane strah od dijeljenja.", "reversed": "Obrnuto govori o pretjeranoj škrtosti ili strahu od gubitka koji koči." },
    "pentacles-05": { "name": "Petica pentakla", "upright": "Petica pentakla govori o oskudici, brigama ili osjećaju izostavljenosti. No podrška je bliže nego što se u hladnoći čini — vrijedi je potražiti. Ova teškoća je prolazna, ne konačna.", "reversed": "Obrnuto znači oporavak od teškog razdoblja ili pronalazak podrške koja je nedostajala." },
    "pentacles-06": { "name": "Šestica pentakla", "upright": "Šestica pentakla nosi velikodušnost, dijeljenje i pravednu razmjenu. Bilo da daješ ili primaš, ravnoteža u davanju ovdje je ključna. Sadašnji trenutak nosi obilje koje se vraća.", "reversed": "Obrnuto ukazuje na neravnotežu u davanju i primanju, ili uvjetovanu velikodušnost." },
    "pentacles-07": { "name": "Sedmica pentakla", "upright": "Sedmica pentakla poziva na strpljivu procjenu uloženog truda prije nego nastaviš. Nosi trenutak zastajanja i razmišljanja, ne odustajanja. Ono što si posijala treba još malo vremena da sazre.", "reversed": "Obrnuto može značiti nestrpljenje s rezultatima ili trud koji se ne isplati odmah." },
    "pentacles-08": { "name": "Osmica pentakla", "upright": "Osmica pentakla slika predanost usavršavanju vještine kroz strpljiv, marljiv rad. Nosi majstorstvo koje dolazi iz ponavljanja i pažnje na detalje. Ustrajnost sada gradi stručnost sutra.", "reversed": "Obrnuto govori o površnom radu ili nedostatku motivacije za usavršavanje." },
    "pentacles-09": { "name": "Devetka pentakla", "upright": "Devetka pentakla uživa u plodovima samostalno izgrađenog uspjeha i udobnosti. Nosi neovisnost, sigurnost i zasluženo zadovoljstvo. Ovo je trenutak da uživaš u onome što si sama postigla.", "reversed": "Obrnuto ukazuje na financijsku nesigurnost ili prekomjernu ovisnost o drugima." },
    "pentacles-10": { "name": "Desetka pentakla", "upright": "Desetka pentakla predstavlja trajno blagostanje, obiteljsko nasljeđe i dugoročnu sigurnost. Nosi obilje koje nadživljuje pojedinca i temelj koji ostaje. Ono što se gradi sada, traje generacijama.", "reversed": "Obrnuto znači obiteljske sukobe oko naslijeđa ili nestabilnost temelja." },
    "pentacles-page": { "name": "Paž pentakla", "upright": "Paž pentakla marljivo uči i planira nove prilike, s obje noge čvrsto na zemlji. Nosi vijest, priliku ili ideju vrijednu ozbiljnog razmatranja. Predanost učenju sada se isplati kasnije.", "reversed": "Obrnuto može značiti nerealne planove ili nedostatak discipline u učenju." },
    "pentacles-knight": { "name": "Vitez pentakla", "upright": "Vitez pentakla napreduje polako, ali postojano, oslonjen na pouzdanost i rutinu. Nosi ustrajnost, odgovornost i temeljit pristup. Njegova sporost nije zastoj, nego sigurnost.", "reversed": "Obrnuto ukazuje na inertnost, tvrdoglavost ili otpor promjeni rutine." },
    "pentacles-queen": { "name": "Kraljica pentakla", "upright": "Kraljica pentakla njeguje udobnost, obilje i praktičnu brigu o sebi i drugima. Spaja toplinu doma s poslovnom sposobnošću i velikodušnošću. U njezinoj blizini stvari cvjetaju i napreduju.", "reversed": "Obrnuto znači zanemarivanje sebe zbog brige o drugima, ili materijalnu nesigurnost." },
    "pentacles-king": { "name": "Kralj pentakla", "upright": "Kralj pentakla utjelovljuje stabilnost, materijalni uspjeh i pouzdano vodstvo izgrađeno kroz godine truda. Nosi sigurnost, izobilje i sposobnost da se brine za druge. Ono što gradi, gradi da traje.", "reversed": "Obrnuto govori o pohlepi, tvrdoglavosti ili opsjednutosti materijalnim uspjehom." }
  },
  "marseille": {}
};
